<?php defined('ABSPATH') || exit; ?>
<header class="pp-page-heading pc-heading"><div><p class="pp-eyebrow"><?php esc_html_e('Petish Passport · Pet Club','petish-passport'); ?></p><h1><?php esc_html_e('Meet the little neighbours.','petish-passport'); ?></h1><p class="pp-intro"><?php esc_html_e('Small pets, big personalities. A little community made by their people.','petish-passport'); ?></p></div><a class="pp-button pp-button-secondary" href="<?php echo esc_url(self::url()); ?>"><?php echo self::icon('plus'); ?><?php echo esc_html(is_user_logged_in()?__('My Pets','petish-passport'):__('Join the little community','petish-passport')); ?></a></header>
