<?php if($profiles): ?><div class="pc-community-grid"><?php foreach($profiles as $profile): ?><article class="pc-community-card"><a class="pc-community-photo" href="<?php echo esc_url($profile['url']); ?>"><?php echo self::public_avatar($profile,true); ?></a><div class="pc-community-info"><p class="pp-eyebrow"><?php echo esc_html(self::label('species',$profile['species'])); ?></p><h2><a href="<?php echo esc_url($profile['url']); ?>"><?php echo esc_html($profile['name']); ?></a></h2><?php if($profile['bio']): ?><p class="pc-community-bio"><?php echo esc_html($profile['bio']); ?></p><?php endif; ?><div class="pc-community-bottom"><span class="pc-mini-heart"><?php echo self::icon('heart'); ?><?php echo esc_html(number_format_i18n($profile['hearts'])); ?></span><a class="pc-text-link" href="<?php echo esc_url($profile['url']); ?>"><?php esc_html_e('Meet me','petish-passport'); ?> <span aria-hidden="true">→</span></a></div></div></article><?php endforeach; ?></div>
<?php else: ?><section class="pc-empty pc-welcome"><span class="pc-empty-icon"><?php echo self::icon('heart'); ?></span><h2><?php esc_html_e('A little community starts here.','petish-passport'); ?></h2><p><?php esc_html_e('There are no shared Passports yet. Create a private Passport for your pet, then choose whether to introduce them to the club.','petish-passport'); ?></p><a class="pp-button" href="<?php echo esc_url(self::url()); ?>"><?php esc_html_e('Visit My Pets','petish-passport'); ?></a></section><?php endif; ?>
<p class="pc-inline-note"><?php echo self::icon('lock'); ?><?php esc_html_e('Every pet here was shared by its owner. Private Passports never appear in the club.','petish-passport'); ?></p>
